+			// its entry point.
+			const packageBase = pathToFileURL(path.join(packagePath, 'noop.js')).toString();
+			const resolved = resolve(specifier, packageBase);
+
+			return fileURLToPath(resolved);
+		} catch {
+			return undefined;
+		}
+	}
